/**
 * Browser half: the Session map plugin.
 *
 * Contributes three bodies and two right-sidebar tab types: a plain overview as
 * a Conversation tab and as a right-column tab, a fork-tree canvas as a
 * Conversation tab, a right-column tab, and a Session header launcher.
 *
 * Services are read through `ctx.get` against local structural types rather
 * than the product's own browser packages: those are published at a prerelease
 * version, and this repository deliberately does not pin them. The same reason
 * makes the stylesheet travel as a string — there is no `styles` service
 * outside the dynamic runtime — so `apply` owns the `<style>` element itself.
 *
 * @module dsh-session-map/client
 */
import type { Context } from '@deepseek-ai/cordis'
import type { ReactElement } from 'react'
import { createAcpCard, type ConfigFormsLike } from './acp-card'
import { ACP_HINT_CELL_ID, createAcpHint } from './acp-hint'
import { AcpToolRow, ACP_TOOL_KEYS, type AcpToolRowProps } from './acp-tool-row'
import { CSS } from './css'
import { MAP_KIND, MAP_TYPE_ID, OVERVIEW_KIND, OVERVIEW_TYPE_ID } from './constants'
import { createFlag } from './flags'
import { installModelScope, readModelScopeMode, type PresetFace } from './model-scope'
import { ACP_MODE_CELL_ID, createAcpModeSelect, type AcpModeCommandsFace } from './acp-mode-card'
import {
  createMapLauncher,
  createMapView,
  createOverviewTab,
  SidebarOverviewBody,
  type MapFlags,
  type SessionMapRuntime,
  type SidebarRightFace,
} from './views'

/** Plugin name the Loader reports for this bundle's browser half. */
export const name = 'dsh-session-map'

/** Hard dependency: there is nothing to register into before the slot registry exists. */
export const inject = ['slots']

/** Structural view of the context's untyped service lookup, which this program does not declare. */
interface ServiceLocator {
  get(name: string): unknown
}

/** One entry's registration options, across the cardinalities this plugin uses. */
interface SlotRegistrationOptions {
  readonly name: string
  /** List-cell key; required by a list slot. */
  readonly id?: string
  /** Keyed-cell key; required by a keyed slot. */
  readonly key?: string
  readonly order?: number
  readonly label?: string
}

/** The slot-registry operations this plugin calls. */
interface SlotsService {
  /**
   * Run a registration while a slot key is declared, and drop it when that declaration collapses.
   * @param key - the slot key to wait for.
   * @param callback - the registration body.
   * @returns the injected registration's disposer.
   */
  inject(key: string, callback: () => () => void): () => void
  /**
   * Register one entry into a declared slot.
   * @param options - the slot key plus the options its cardinality takes.
   * @param component - the entry's body.
   * @returns the registration's disposer.
   */
  register<P>(options: SlotRegistrationOptions, component: (props: P) => ReactElement): () => void
}

/** One guide-page capsule a tab type offers. */
interface SidebarRightGuideEntry {
  readonly order: number
  readonly title: () => string
  readonly description?: (() => string) | undefined
}

/** One registered right-sidebar tab type, as this plugin declares it. */
interface SidebarRightTabDefinition {
  readonly id: string
  readonly kind: string
  readonly title: (address: string) => string
  readonly guide?: readonly SidebarRightGuideEntry[] | undefined
}

/** The right-sidebar tab-type registry (stage one of a tab registration). */
interface SidebarRightTabsService {
  /**
   * The type in force for a kind.
   * @param kind - the type discriminator.
   * @returns the type, or `undefined` when nothing registered it.
   */
  get(kind: string): SidebarRightTabDefinition | undefined
  /**
   * Register one tab type for the caller's lifetime.
   * @param definition - the contributed type.
   * @returns idempotent disposer.
   */
  register(definition: SidebarRightTabDefinition): () => void
}

/** Workspace navigation, as far as opening one Session needs. */
interface UiWorkspaceService {
  openSession(sessionId: string): void
}

/** Session Controller navigation, the fallback when the Workspace UI is absent. */
interface SessionsService {
  open(sessionId: string): void
  /**
   * The sessions store, which is where a Session's own preset is readable.
   *
   * Not `binding.session.projections.faceOf('agentPreset')`: the projection faces
   * this product exposes are `inbox`, `goal`, `userQuestions`, `modelSelection`,
   * `plan` and `permissions`, while every preset read in the shipped client goes
   * through this store's `projectionValues.agentPreset`
   * (`ui-agent-preset`, `ui-session`, the sidebar).
   */
  readonly list?: {
    getSnapshot(): {
      readonly byId?: Record<string, {
        /** Whether no turn has run yet, which is what the composer notice gates on. */
        readonly blank?: unknown
        readonly projectionValues?: { readonly agentPreset?: unknown }
      } | undefined>
    }
    subscribe(listener: () => void): () => void
  }
}

/**
 * The client `modelDirectories` service, as far as the model scope uses it.
 *
 * Untyped by the product's own packages on purpose (this repository pins none of
 * them); the shape is the one `@deepseek-ai/dsh-client-ui-model-selection` calls.
 */
interface ModelDirectoriesService {
  /**
   * @param sessionId - the Session whose model directory is wanted.
   * @returns the per-Session directory both model pickers read.
   */
  directoryFor(sessionId: string): unknown
}

/**
 * The client Remote gateway, as far as the model scope uses it.
 *
 * The Session namespace is the same wire face the shipped picker writes through,
 * so a reconciliation is indistinguishable from a person choosing that model.
 */
interface RemoteService {
  readonly session?: {
    /**
     * @param request - the Session and the provider/model to record for it.
     * @returns the Remote outcome.
     */
    selectModel?(request: { sessionId: string; provider: string; model: string }): Promise<unknown>
  }
}

/** A lifecycle effect body: what it installs, and the disposer that releases it. */
type EffectBody = () => () => void

/**
 * Read one optional service from the global store.
 *
 * The context's declared surface carries none of these prerelease services, so
 * the lookup is typed here instead of imported; `undefined` means nothing is
 * providing the name right now.
 * @param ctx - the plugin's context.
 * @param name - the service name.
 * @returns the service as the caller's local interface, or `undefined`.
 */
function lookup<T>(ctx: Context, name: string): T | undefined {
  const locator = ctx as unknown as ServiceLocator
  // Never throws. Inside an *inject scope* `get` throws for a service the scope did
  // not declare, and Cordis swallows an exception thrown from an inject callback —
  // which is exactly how the ACP model scope previously died without a trace.
  try {
    return locator.get(name) as T | undefined
  } catch {
    return undefined
  }
}

/**
 * Browser-local preference holding whether the Conversation tab entries are
 * registered.
 *
 * Not row config: the browser half is created by the web boot with a bare
 * `{ name }` (`packages/client/web/src/boot-client.ts`), and a boot manifest
 * row carries only `id`, `inject`, and `immediately`, so nothing a profile
 * writes reaches this program.
 */
const CONVERSATION_VIEWS_KEY = 'dsh.session-map.conversationViews'

/**
 * Whether the Conversation tabs are registered when this browser recorded no
 * preference. The header launcher and both right-column tab types register
 * either way, so the map stays usable from the right column alone.
 */
const DEFAULT_CONVERSATION_VIEWS = false

/**
 * Read this browser's Conversation-tab preference.
 * @returns true when the tabs should be registered.
 */
function conversationViewsEnabled(): boolean {
  if (typeof localStorage === 'undefined') return DEFAULT_CONVERSATION_VIEWS
  try {
    const stored = localStorage.getItem(CONVERSATION_VIEWS_KEY)
    if (stored === 'true') return true
    if (stored === 'false') return false
  } catch {
    // Storage can be denied (private mode, blocked site data); the shipped
    // default is the reading of "no preference recorded".
  }
  return DEFAULT_CONVERSATION_VIEWS
}

/**
 * Client plugin body: inject the stylesheet, build the three bodies over one set
 * of plugin-run switches, and register every seat and tab type.
 * @param ctx - browser root context carrying the slot registry.
 */
export function apply(ctx: Context): void {
  const slots = lookup<SlotsService>(ctx, 'slots')
  if (slots === undefined) return

  // The product has no `styles` service outside the dynamic runtime, so the
  // sheet is a string this effect owns: one element, removed with the fiber.
  ctx.effect(() => {
    const element = document.createElement('style')
    element.textContent = CSS
    document.head.appendChild(element)
    return () => { element.remove() }
  }, 'session-views: stylesheet')

  // Toolbar preferences live on the plugin run, not on one mounted View:
  // switching Session unmounts and remounts this View.
  const showPromptsFlag = createFlag(false)
  const hideSubagentsFlag = createFlag(true)
  // Per-line overrides. Two sets, each recording one user gesture in the mode
  // it was made in, so flipping the global switch restores rather than
  // inverts what the other mode had.
  const openedLinesFlag = createFlag(new Set<string>())
  const collapsedLinesFlag = createFlag(new Set<string>())
  // Session ids whose inherited turn prefix is expanded rather than folded.
  const expandedInheritedFlag = createFlag(new Set<string>())

  const flags: MapFlags = {
    showPrompts: showPromptsFlag,
    hideSubagents: hideSubagentsFlag,
    openedLines: openedLinesFlag,
    collapsedLines: collapsedLinesFlag,
    expandedInherited: expandedInheritedFlag,
  }

  const runtime: SessionMapRuntime = {
    sidebarRight: () => {
      const service = lookup<SidebarRightFace>(ctx, 'sidebarRight')
      if (service === undefined) throw new Error('右侧栏服务 sidebarRight 不可用')
      return service
    },
    openSession: (sessionId) => {
      const uiWorkspace = lookup<UiWorkspaceService>(ctx, 'uiWorkspace')
      if (uiWorkspace !== undefined && typeof uiWorkspace.openSession === 'function') {
        uiWorkspace.openSession(sessionId)
        return
      }
      const sessions = lookup<SessionsService>(ctx, 'sessions')
      if (sessions !== undefined && typeof sessions.open === 'function') sessions.open(sessionId)
    },
  }

  const MapLauncher = createMapLauncher(runtime)
  const OverviewTab = createOverviewTab(runtime)
  const SessionMapTab = createMapView(runtime, flags, true)
  const SidebarMapBody = createMapView(runtime, flags, false)

  ctx.effect(() => slots.inject('conversation.session.header.utilities', () => slots.register(
    { name: 'conversation.session.header.utilities', id: 'session-map-launcher', order: 40 },
    MapLauncher,
  )), 'session-map: header launcher')

  // The mirrored ACP tool rows. `tool.call.toolview` is keyed by wire tool name
  // and its key domain is open by contract, so claiming our own names is the
  // supported route; without this the shell's generic row labels each call with
  // the tool name and an internal call id. The slot declares one entry per key,
  // so the loop registers and disposes them together.
  ctx.effect(() => slots.inject('tool.call.toolview', () => {
    const disposers = ACP_TOOL_KEYS.map((key) => slots.register<AcpToolRowProps>(
      { name: 'tool.call.toolview', key },
      AcpToolRow,
    ))
    return () => { for (const dispose of disposers) dispose() }
  }), 'session-map: acp tool rows')

  // The Conversation tab entries are opt-in; see DEFAULT_CONVERSATION_VIEWS.
  if (conversationViewsEnabled()) {
    ctx.effect(() => slots.inject('conversation.view', () => slots.register(
      { name: 'conversation.view', id: 'session-overview', order: 20, label: '概览' },
      OverviewTab,
    )), 'session-overview: conversation view entry')

    ctx.effect(() => slots.inject('conversation.view', () => slots.register(
      { name: 'conversation.view', id: 'session-map', order: 30, label: '会话图谱' },
      SessionMapTab,
    )), 'session-map: conversation view entry')
  }

  // The right column's type registry belongs to another package whose own
  // injections are wider, so its apply can land after this one. Reading the
  // service once at this point would find nothing, drop both tab types, and
  // leave the header button opening a kind nothing registered. Waiting on it
  // here keeps the Conversation seats available in a composition that mounts no
  // right column at all, which a plugin-level inject would not.
  ctx.inject(['slots', 'sidebarRightTabs'], (scope) => {
    const scopedSlots = lookup<SlotsService>(scope, 'slots')
    const sidebarRightTabs = lookup<SidebarRightTabsService>(scope, 'sidebarRightTabs')
    if (scopedSlots === undefined || sidebarRightTabs === undefined) return

    // A page kept open across a host restart still runs the previous incarnation
    // of this plugin, which already holds the same type. Reusing that one is
    // safe: every other cell is re-registered below under a later priority, so
    // the new bodies win. A DIFFERENT type holding the kind is a real wiring
    // conflict and still fails loud.
    const claimType = (
      id: string,
      kind: string,
      title: () => string,
      guideTitle?: () => string,
      guideDescription?: () => string,
    ): EffectBody => {
      return () => {
        const existing = sidebarRightTabs.get(kind)
        if (existing !== undefined) {
          if (existing.id === id) return () => {}
          throw new Error(
            'sidebarRight: kind "' + kind + '" is already held by tab type "' + existing.id + '"',
          )
        }
        const definition: SidebarRightTabDefinition = guideTitle === undefined
          ? { id, kind, title }
          : { id, kind, title, guide: [{ order: 20, title: guideTitle, description: guideDescription }] }
        return sidebarRightTabs.register(definition)
      }
    }

    ctx.effect(
      claimType(OVERVIEW_TYPE_ID, OVERVIEW_KIND, () => '会话概览'),
      'session-overview: rightbar tab type',
    )
    ctx.effect(() => scopedSlots.inject('sidebar.right.pane.tab', () => scopedSlots.register(
      { name: 'sidebar.right.pane.tab', key: OVERVIEW_TYPE_ID },
      SidebarOverviewBody,
    )), 'session-overview: rightbar tab body')

    ctx.effect(
      claimType(
        MAP_TYPE_ID,
        MAP_KIND,
        () => '会话图谱',
        () => '会话图谱',
        () => '所有会话的 fork 树画布',
      ),
      'session-map: rightbar tab type',
    )
    ctx.effect(() => scopedSlots.inject('sidebar.right.pane.tab', () => scopedSlots.register(
      { name: 'sidebar.right.pane.tab', key: MAP_TYPE_ID },
      SidebarMapBody,
    )), 'session-map: rightbar tab body')
  })

  // The ACP vendor page. It rides an OPTIONAL injection: a composition that
  // never mounted the settings domain still gets the whole canvas above, and
  // only a profile running the ACP route ever has a namespace to edit. The page
  // registers unconditionally (rather than through `whileServed`) so a profile
  // that disabled the row still gets the explanation of how to bring it back.
  ctx.inject(['slots', 'configForms'], (scope) => {
    const scopedSlots = lookup<SlotsService>(scope, 'slots')
    const configForms = lookup<ConfigFormsLike>(scope, 'configForms')
    if (scopedSlots === undefined || configForms === undefined) return
    const AcpCard = createAcpCard(configForms)
    // After the shipped presets (agent-presets is 20): an agent is what puts a
    // card in the new-session picker, so the roster comes first.
    ctx.effect(() => scopedSlots.inject('settings.section', () => scopedSlots.register(
      { name: 'settings.section', id: 'acp', order: 25, label: 'ACP' },
      AcpCard,
    )), 'session-map: acp vendors settings section')

    // The composer's setup notice (P13) rides the same service from the other end
    // of the problem: the page above is where an agent is added, this is where its
    // absence is felt. `conversation.input.right` is the composer bar's trailing
    // list slot — the notice belongs with the compact tool controls, not in the
    // transcript. Reaching Settings *on a section* is the onboarding owner share's
    // `openSection`, which a composer cell does not receive, so the notice names
    // the page in its own text and stays non-interactive.
    //
    // The blank-Session gate comes from the Sessions store: the mode menu the notice
    // is about exists only on the new-session screen. `sessions` is not an
    // injectable name (an inject scope rejects it) while `get` resolves it, which
    // is how the model scope below reads the same store.
    const sessionsStore = lookup<SessionsService>(ctx, 'sessions')?.list
    const blankOf = (sessionId: string): boolean | undefined => {
      try {
        const row = sessionsStore?.getSnapshot?.()?.byId?.[sessionId]
        return row === undefined ? undefined : row.blank === true
      } catch (error: unknown) {
        // Guarded for the same reason the model scope guards its reads: an
        // unexpected shape here must not throw out of a React render.
        console.warn('dsh-session-map: could not read a Session summary', error)
        return undefined
      }
    }
    const AcpHintCell = createAcpHint(configForms, {
      isBlank: blankOf,
      subscribe: (listener) => {
        try {
          return sessionsStore?.subscribe?.(listener) ?? (() => {})
        } catch {
          return () => {}
        }
      },
    })
    ctx.effect(() => scopedSlots.inject('conversation.input.right', () => scopedSlots.register(
      { name: 'conversation.input.right', id: ACP_HINT_CELL_ID, order: 0 },
      AcpHintCell,
    )), 'session-map: acp setup notice')
  })

  // The ACP model scope (P10). The composer's model card is the product's and
  // stays untouched, so the filter goes where both of its pickers read: the
  // per-Session directory. `directoryFor` is wrapped rather than the service
  // replaced — the product resolves the service once and captures it, while it
  // calls this method on every render.
  //
  // Injected rather than read once, because a composition may mount the service
  // after this plugin, and because a browser half that never finds it must stay
  // exactly as it was: `installModelScope` fails open and this block does nothing.
  ctx.inject(['modelDirectories', 'remote', 'remote.session'], (scope) => {
    // Property access on the injected scope, exactly as the shipped client reads
    // these services. `get` is NOT equivalent here: inside an inject scope it throws
    // for any name the scope did not declare (`cannot get property "remote.session"
    // without inject`), and Cordis swallows what an inject callback throws — which is
    // how this whole feature first died without leaving a trace anywhere. The
    // declared list is therefore exactly what the shipped picker declares for the
    // model card: the directory service and the session Remote it writes through.
    const models = (scope as { modelDirectories?: ModelDirectoriesService }).modelDirectories
    if (models === undefined) return
    const sessionRemote = (scope as { remote?: { session?: RemoteService['session'] } }).remote?.session
      ?? lookup<RemoteService>(ctx, 'remote')?.session
    // The sessions store comes from the plugin context: `sessions` is not an
    // injectable name (the scope rejects it) while `get` resolves it.
    const sessionsStore = lookup<SessionsService>(ctx, 'sessions')?.list
    try {
      // The preset is read from the sessions store, which is where this product
      // keeps it. Every read is guarded: an unexpected shape here must leave the
      // feature inert, never throw out of a React render.
      const readPreset = (sessionId: string): unknown => {
        try {
          return sessionsStore?.getSnapshot?.()?.byId?.[sessionId]?.projectionValues?.agentPreset
        } catch (error: unknown) {
          console.warn('dsh-session-map: could not read a Session preset projection', error)
          return undefined
        }
      }
      // The write a preset card cannot make itself: a card Session routes to its
      // agent while its stored selection is still the profile default, and the
      // reconciliation puts the two back in agreement — in both directions.
      const selectModel = sessionRemote?.selectModel
      ctx.effect(() => installModelScope(
        {
          models,
          presetFaceOf: typeof sessionsStore?.getSnapshot !== 'function' || typeof sessionsStore.subscribe !== 'function'
            ? undefined
            : (sessionId) => ({
              getSnapshot: () => readPreset(sessionId),
              subscribe: (listener) => {
                try {
                  return sessionsStore.subscribe(listener)
                } catch {
                  return () => {}
                }
              },
            }),
          selectModel: typeof selectModel === 'function'
            ? (request) => selectModel.call(sessionRemote, request)
            : undefined,
        },
        {
          mode: () => readModelScopeMode(),
          warn: (message, detail) => { console.warn(message, detail) },
        },
      ), 'session-map: acp model scope')
    } catch (error: unknown) {
      // Fail open, but say so: an exception from a Cordis inject callback is silent
      // otherwise, and that is the failure mode that cost the most time here.
      console.warn('dsh-session-map: the ACP model scope could not be installed', error)
    }
  })

  // The composer's ACP mode control (P11). `conversation.input.left` is the list slot
  // the composer bar declares immediately after the access-mode seat, which is what
  // puts this control to that seat's right — the position the request named. The cell
  // reads the agent's modes by executing the `/acp-mode` command and parsing its
  // answer, because a runtime plugin has no other Host→client channel (see
  // `docs/p11-acp-mode-select.md` §3), and switches them through the same command.
  ctx.inject(['slots', 'remote', 'remote.commands'], (scope) => {
    const scopedSlots = lookup<SlotsService>(scope, 'slots')
    if (scopedSlots === undefined) return
    const commands = (scope as { remote?: { commands?: AcpModeCommandsFace } }).remote?.commands
    const AcpModeSelect = createAcpModeSelect(commands)
    ctx.effect(() => scopedSlots.inject('conversation.input.left', () => scopedSlots.register(
      { name: 'conversation.input.left', id: ACP_MODE_CELL_ID, order: 0 },
      AcpModeSelect,
    )), 'session-map: acp mode control')
  })
}
